function daysUntil(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr + "T00:00:00");
  const now = new Date();
  now.setHours(0, 0, 0, 0);
  return Math.round((d - now) / 86400000);
}

// Répare un équipement dont les données ont été créées avant l'ajout de nouveaux contrôles au
// schéma (mises à jour successives de l'app) : comble les clés manquantes sans toucher aux
// valeurs déjà saisies — évite les plantages (export Word, etc.) et rend les nouveaux champs utilisables.
function repairEquipementControles(eq) {
  const schema = getSchema(eq);
  if (!schema) return eq;
  const controles = { ...eq.controles };
  schema.sections.forEach((sec) => {
    controles[sec.key] = { ...(controles[sec.key] || {}) };
    sec.items.forEach((item) => {
      if (!controles[sec.key][item.key]) {
        const fieldsDefault = {};
        (item.fields || []).forEach((f) => {
          fieldsDefault[f.key] = "";
          if (unitFamilyFor(f.unit)) fieldsDefault[f.key + "Unite"] = f.unit;
        });
        controles[sec.key][item.key] = item.kind === "control" ? { action: "", etat: "Conforme", fields: fieldsDefault } : { fields: fieldsDefault };
      }
    });
    if (!controles[sec.key + "__custom"]) controles[sec.key + "__custom"] = [];
    if (sec.key === "parametrage_relais" && !controles.parametrage_relais_seuils) controles.parametrage_relais_seuils = [emptySeuilEntry(PARAM_SEUIL_TYPES[0])];
  });
  return { ...eq, controles };
}
function createControlesDefaults(schema) {
  const controles = {};
  schema.sections.forEach((sec) => {
    controles[sec.key] = {};
    sec.items.forEach((item) => {
      const fieldsDefault = {};
      (item.fields || []).forEach((f) => {
        fieldsDefault[f.key] = f.defaultValue ?? "";
        if (unitFamilyFor(f.unit)) fieldsDefault[f.key + "Unite"] = f.unit;
      });
      controles[sec.key][item.key] =
        item.kind === "control" ? { action: "", etat: "Conforme", fields: fieldsDefault } : { fields: fieldsDefault };
    });
    controles[sec.key + "__custom"] = [];
    if (sec.key === "parametrage_relais") controles.parametrage_relais_seuils = [emptySeuilEntry(PARAM_SEUIL_TYPES[0])];
  });
  return controles;
}

function emptyEquipement(type) {
  const schema = SCHEMAS[type];
  const identification = {};
  schema.identification.forEach((f) => (identification[f.key] = ""));
  const controles = createControlesDefaults(schema);
  if (type === "Sécurité") {
    Object.keys(controles.materiel_securite).forEach((k) => { controles.materiel_securite[k].fields.present = "OUI"; });
  }
  if (TYPES_AVEC_TC.includes(type)) {
    // Sur Interrupteur HTA / Interrupteur Fusible HTA (pas de relais de protection dédié), le TC
    // homopolaire est la priorité — c'est lui qui est proposé par défaut à la création.
    const fonctionParDefaut = (type === "Interrupteur HTA" || type === "Interrupteur Fusible HTA") ? "Homopolaire (terre)" : LISTE_TC_FONCTION[0];
    const premierTC = emptyDynamicEntry(fonctionParDefaut, TC_FIELDS_DYNAMIC, true);
    premierTC.fields.fonction = fonctionParDefaut;
    controles.tc_dynamique = [premierTC];
  }
  if (TYPES_AVEC_MANOEUVRE_DYNAMIQUE.includes(type)) controles.manoeuvre_dynamique = [emptyDynamicEntry(LISTE_TYPE_INT_SECT[0], [], true)];
  if (TYPES_AVEC_ORGANES_DYNAMIQUE.includes(type)) controles.organes_dynamique = [emptyDynamicEntry("", ORGANES_FIELDS, false)];
  if (TYPES_AVEC_GRADINS.includes(type)) controles.gradins_dynamique = [emptyDynamicEntry(LISTE_NOM_GRADIN[0], GRADIN_FIELD_DEFS, true)];
  if (TYPES_AVEC_BRANCHES_UPS.includes(type)) {
    controles.branches_dynamique = [emptyDynamicEntry(LISTE_NOM_BRANCHE[0], BRANCHE_FIELD_DEFS, true)];
    controles.elements_dynamique = [emptyDynamicEntry("Élément 1", ELEMENT_FIELD_DEFS, false)];
    controles.releve_config = { mode: "Floating", saisieParGroupe: false, tailleGroupe: 2, toleranceBasse: 3, toleranceHaute: 3 };
  }
  if (TYPES_AVEC_PIECES_USURE.includes(type)) {
    controles.pieces_usure_ups = {};
    getCategoriesUsure(type).forEach((cat) => { controles.pieces_usure_ups[cat.key] = [emptyModeleUsure(cat.dureeDefaut)]; });
  }
  if (type === "Onduleur" || type === "Redresseur chargeur") controles.regimes_reseaux = { normal: "Triphasé", secours: "Triphasé", utilisation: "Triphasé", onduleur: "Triphasé" };
  if (type === "Inverseur de source") controles.regimes_reseaux = { source1: "Triphasé", source2: "Triphasé", utilisation: "Triphasé" };
  if (TYPES_AVEC_MESURES_UTILISATION.includes(type)) controles.photos_utilisation = { l1: [], l2: [], l3: [] };
  if (type === "Redresseur chargeur") controles.photos_reseau_entree = { l1: [], l2: [], l3: [] };
  return {
    id: uid(),
    lignageId: uid(), // identifiant stable de l'équipement physique, conservé d'une visite à l'autre
    type,
    ordre: 0, // détermine la position dans le rapport — réattribué séquentiellement à la création
    localId: "",
    identification,
    controles,
    etatFinal: "Conforme",
    remarques: "",
    photos: [],
    courbeFiles: [],
    courbeDechargeFiles: [],
    rapportLaboFiles: [],
  };
}
// Reprend un équipement existant (visite précédente) pour une nouvelle visite : conserve
// l'identification (marque, modèle, calibre, TC...) mais repart de contrôles/mesures vierges.
// Le lignageId est conservé pour permettre l'historique (taux de charge par exemple) d'une année sur l'autre.
function dupliquerEquipementPourNouvelleVisite(source) {
  const fresh = emptyEquipement(source.type);
  fresh.identification = { ...source.identification };
  fresh.lignageId = source.lignageId || source.id;
  return fresh;
}

