// Rassemble toutes les photos d'un équipement (photos générales, courbes, laboratoire, et toutes
// les photos rattachées à un contrôle ou une liste dynamique — TC, organes, gradins, éléments,
// branches, manœuvres, photos par phase...), avec une légende reprenant le libellé du schéma.
function collectPhotosEquipement(eq) {
  const result = [];
  const addPhotos = (files, caption) => { (files || []).forEach((p) => { if (p && p.dataUrl) result.push({ dataUrl: p.dataUrl, caption }); }); };
  addPhotos(eq.photos, "Photo générale de l'équipement");
  addPhotos(eq.courbeFiles, "Courbe");
  addPhotos(eq.courbeDechargeFiles, "Courbe de décharge batterie");
  addPhotos(eq.rapportLaboFiles, "Rapport laboratoire");
  const schema = getSchema(eq);
  const labelFor = (secKey, itemKey) => {
    const sec = schema && schema.sections && schema.sections.find((s) => s.key === secKey);
    const item = sec && sec.items && sec.items.find((i) => i.key === itemKey);
    return item ? item.label : itemKey;
  };
  const PHASE_SECTION_LABEL = { photos_utilisation: "Utilisation", photos_reseau_entree: "Réseau d'entrée" };
  const controles = eq.controles || {};
  Object.keys(controles).forEach((secKey) => {
    const val = controles[secKey];
    if (Array.isArray(val)) {
      val.forEach((entry) => addPhotos(entry.photos, entry.label || secKey));
    } else if (val && typeof val === "object") {
      ["l1", "l2", "l3"].forEach((ph) => { if (Array.isArray(val[ph])) addPhotos(val[ph], `${PHASE_SECTION_LABEL[secKey] || secKey} — ${ph.toUpperCase()}`); });
      Object.keys(val).forEach((itemKey) => {
        const item = val[itemKey];
        if (item && Array.isArray(item.photos)) addPhotos(item.photos, labelFor(secKey, itemKey));
      });
    }
  });
  return result;
}
// Récupère les octets d'une photo stockée sur Firebase Storage (URL courte) et la convertit en
// data: URL base64 — nécessaire uniquement le temps de générer le Word, puisque la bibliothèque
// docx attend les images en mémoire, pas une URL à télécharger elle-même.
async function urlToDataUrl(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Téléchargement photo impossible (${res.status})`);
  const blob = await res.blob();
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error("lecture impossible"));
    reader.readAsDataURL(blob);
  });
}
// Parcourt une copie du site/de l'intervention et remplace chaque URL Storage par son contenu en
// base64, pour que le reste de la génération Word (docxImage) fonctionne exactement comme avant,
// sans aucune modification — seule cette étape de préparation est nouvelle.
async function resolvePhotosForDocx(obj) {
  const clone = JSON.parse(JSON.stringify(obj));
  const nodes = [];
  (function walk(node) {
    if (Array.isArray(node)) { node.forEach(walk); return; }
    if (node && typeof node === "object") {
      if (typeof node.dataUrl === "string" && node.dataUrl.startsWith("http")) nodes.push(node);
      Object.values(node).forEach(walk);
    }
  })(clone);
  await Promise.all(nodes.map(async (node) => {
    try { node.dataUrl = await urlToDataUrl(node.dataUrl); }
    catch (e) { console.error("[Word] Photo introuvable, ignorée :", e); node.dataUrl = null; }
  }));
  return clone;
}
// Génère un fichier Word séparé regroupant l'ensemble des photos du site, classées par équipement
// puis par contrôle d'origine (au lieu d'être dispersées dans le rapport principal).
async function generateAnnexePhotosDocx(site) {
  await ensureDocx();
  site = await resolvePhotosForDocx(site);
  const logoImg = docxImage(LOGO_DARK, 46, 35);
  const headerTable = new DOCX.Table({ width: { size: 8800, type: DOCX.WidthType.DXA }, columnWidths: [8800], rows: [new DOCX.TableRow({ children: [new DOCX.TableCell({
    width: { size: 8800, type: DOCX.WidthType.DXA }, shading: { type: DOCX.ShadingType.CLEAR, fill: DOCX_DARK },
    children: [new DOCX.Paragraph({ spacing: { before: 120, after: 40 }, children: [
      ...(logoImg ? [logoImg, new DOCX.TextRun({ text: "   ", size: 2 })] : []),
      new DOCX.TextRun({ text: "ANNEXE PHOTOS", bold: true, color: DOCX_WHITE, size: 24 }),
    ] }),
    new DOCX.Paragraph({ spacing: { after: 120 }, children: [new DOCX.TextRun({ text: [site.nom, site.client].filter(Boolean).join(" — "), color: DOCX_SILVER, size: 20 })] })],
  })] })] });
  const children = [headerTable, docxSpacer(160)];
  let total = 0;
  site.equipements.forEach((eq) => {
    const photos = collectPhotosEquipement(eq);
    if (!photos.length) return;
    total += photos.length;
    children.push(docxEquipHeader(eq.type + (eq.identification.repere ? " — " + eq.identification.repere : ""), null));
    photos.forEach((p) => {
      const img = docxImage(p.dataUrl, 260, 195);
      if (!img) return;
      children.push(new DOCX.Paragraph({ spacing: { before: 60, after: 4 }, children: [new DOCX.TextRun({ text: p.caption, bold: true, size: 16, color: DOCX_DARK })] }));
      children.push(new DOCX.Paragraph({ spacing: { after: 40 }, children: [img] }));
    });
  });
  const photosSite = (site.rapport && site.rapport.photos) || [];
  if (photosSite.length) {
    children.push(docxEquipHeader("Photos générales du site", null));
    photosSite.forEach((p) => {
      const img = docxImage(p.dataUrl, 260, 195);
      if (img) { children.push(new DOCX.Paragraph({ spacing: { after: 40 }, children: [img] })); total++; }
    });
  }
  if (total === 0) children.push(new DOCX.Paragraph({ children: [new DOCX.TextRun({ text: "Aucune photo n'a été ajoutée sur ce site.", italics: true, size: 20, color: "666666" })] }));
  const doc = new DOCX.Document({ features: { updateFields: true }, sections: [{ properties: { page: { margin: { top: 500, bottom: 500, left: 600, right: 600 } } }, footers: { default: docxFooterPagination() }, children }] });
  return DOCX.Packer.toBlob(doc);
}
