function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

// Accès à Firestore via son API REST (simples requêtes HTTPS) plutôt que via le SDK temps réel
// (WebChannel/long-polling), qui reste bloqué indéfiniment (ni succès ni erreur) dans certains
// environnements réseau — une requête HTTPS classique est bien plus difficile à bloquer ainsi.
// Contrepartie : pas de mise à jour instantanée entre techniciens, remplacée par une actualisation
// périodique (voir REST_POLL_INTERVAL_MS).
const FIRESTORE_REST_BASE = "https://firestore.googleapis.com/v1/projects/ht-maintenance/databases/(default)/documents";
// Bucket Firebase Storage (voir firebase.js) — les photos y sont uploadées individuellement au lieu
// d'être stockées en base64 dans le document Firestore, qui plafonne à 1 Mo par document et ne
// peut absorber que quelques photos avant d'échouer silencieusement.
const STORAGE_BUCKET = "ht-maintenance.firebasestorage.app";
async function firebaseStorageUpload(path, blob, idToken) {
  const encodedPath = encodeURIComponent(path);
  const url = `https://firebasestorage.googleapis.com/v0/b/${STORAGE_BUCKET}/o?uploadType=media&name=${encodedPath}`;
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": blob.type || "application/octet-stream", Authorization: `Bearer ${idToken}` },
    body: blob,
  });
  if (!res.ok) throw new Error(`Firebase Storage upload ${res.status}`);
  const data = await res.json();
  return `https://firebasestorage.googleapis.com/v0/b/${STORAGE_BUCKET}/o/${encodedPath}?alt=media&token=${data.downloadTokens}`;
}
// Convertit un data: URL (base64) existant en Blob, pour migrer les anciennes photos vers Storage.
function dataUrlToBlob(dataUrl) {
  const match = dataUrl.match(/^data:(.*?);base64,(.*)$/);
  if (!match) throw new Error("dataUrl invalide");
  const mime = match[1];
  const binary = atob(match[2]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}
// L'utilisateur courant, mis à jour par le composant racine — évite de faire traverser `currentUser`
// à travers des dizaines de composants intermédiaires (galeries de photos imbriquées profondément).
let CURRENT_USER_FOR_STORAGE = null;
const REST_POLL_INTERVAL_MS = 7000;
async function firestoreRestGet(docPath, idToken) {
  const res = await fetch(`${FIRESTORE_REST_BASE}/${docPath}`, { headers: { Authorization: `Bearer ${idToken}` } });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Firestore REST GET ${res.status}`);
  return res.json();
}
async function firestoreRestSet(docPath, valueJson, updatedAt, updatedBy, idToken) {
  const body = { fields: { value: { stringValue: valueJson }, updatedAt: { integerValue: String(updatedAt) }, updatedBy: { stringValue: updatedBy || "" } } };
  const url = `${FIRESTORE_REST_BASE}/${docPath}?updateMask.fieldPaths=value&updateMask.fieldPaths=updatedAt&updateMask.fieldPaths=updatedBy`;
  const res = await fetch(url, { method: "PATCH", headers: { "Content-Type": "application/json", Authorization: `Bearer ${idToken}` }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`Firestore REST PATCH ${res.status}`);
  return res.json();
}

export default function App({ currentUser, onLogout }) {
  useEffect(() => { CURRENT_USER_FOR_STORAGE = currentUser; }, [currentUser]);
  const [sites, setSites] = useState([]);
  // Miroir synchrone de `sites`, lu par le poll et la migration photo — une ref est à jour
  // immédiatement (contrairement à une closure capturée au moment de la création de l'effet).
  const sitesRefForPoll = useRef([]);
  useEffect(() => { sitesRefForPoll.current = sites; }, [sites]);
  const [loaded, setLoaded] = useState(false);
  const [selectedId, setSelectedId] = useState(null);
  const [reprendreSiteOpen, setReprendreSiteOpen] = useState(false);
  const [saveError, setSaveError] = useState(false);
  const [printSite, setPrintSite] = useState(null);
  const [printAnnexeSite, setPrintAnnexeSite] = useState(null);
  const [exportConfirm, setExportConfirm] = useState(null);
  const saveTimer = useRef(null);
  const lastSyncedSites = useRef(null); // dernier contenu (JSON) connu comme synchronisé avec le serveur
  const writeInFlight = useRef(false); // verrou dur : empêche toute nouvelle écriture tant que la précédente n'est pas terminée
  const saveErrorRef = useRef(false); // miroir synchrone de saveError, lu par le poll (les refs sont à jour immédiatement, contrairement au state)
  const pendingRetrySites = useRef(null); // dernier JSON qui a échoué à l'écriture, à retenter automatiquement

  const [view, setView] = useState("sites"); // "sites" | "interventions" | "calendrier"
  const [interventions, setInterventions] = useState([]);
  const ivRefForPoll = useRef([]);
  useEffect(() => { ivRefForPoll.current = interventions; }, [interventions]);
  const [ivLoaded, setIvLoaded] = useState(false);
  const [selectedIvId, setSelectedIvId] = useState(null);
  const [printIv, setPrintIv] = useState(null);
  const ivSaveTimer = useRef(null);
  const lastSyncedIv = useRef(null);
  const ivWriteInFlight = useRef(false);

  // Registre des clients — permet d'enregistrer un client (nom + e-mail) à l'avance, sans avoir à
  // créer un site complet ; partagé entre techniciens comme sites/interventions.
  const [clientsRegistry, setClientsRegistry] = useState([]);
  const clientsRefForPoll = useRef([]);
  useEffect(() => { clientsRefForPoll.current = clientsRegistry; }, [clientsRegistry]);
  const [clientsLoaded, setClientsLoaded] = useState(false);
  const clientsSaveTimer = useRef(null);
  const lastSyncedClients = useRef(null);
  const clientsWriteInFlight = useRef(false);
  const [gererClientsOpen, setGererClientsOpen] = useState(false);

  // Bibliothèque des caractéristiques (marque, modèle, type...) déjà saisies par équipement — toute
  // valeur tapée dans un champ à suggestions rejoint automatiquement les propositions futures pour
  // ce même champ, sur ce même type d'équipement. Partagée entre techniciens comme les clients.
  const [caracteristiquesLibrary, setCaracteristiquesLibrary] = useState({});
  const caracRefForPoll = useRef({});
  useEffect(() => { caracRefForPoll.current = caracteristiquesLibrary; }, [caracteristiquesLibrary]);
  const [caracLoaded, setCaracLoaded] = useState(false);
  const caracSaveTimer = useRef(null);
  const lastSyncedCarac = useRef(null);
  const caracWriteInFlight = useRef(false);

  // Synchronisation via l'API REST de Firestore : tous les techniciens connectés partagent le
  // même document "sites" et "interventions". Une actualisation périodique (toutes les 7s) fait
  // apparaître les changements d'un collègue — pas instantané comme avant, mais bien plus fiable
  // (voir le commentaire sur FIRESTORE_REST_BASE plus haut).
  useEffect(() => {
    let cancelled = false;
    let intervalId = null;
    async function poll() {
      if (!currentUser) return;
      if (writeInFlight.current) return; // n'écrase pas l'état local pendant une écriture en cours
      if (saveErrorRef.current) return; // la dernière écriture a échoué : l'état local est "en avance"
      // sur le serveur (ex. une photo tout juste ajoutée) — ne jamais l'écraser tant que la
      // sauvegarde n'a pas réussi, sous peine de faire disparaître silencieusement les changements.
      try {
        const idToken = await currentUser.getIdToken();
        const data = await firestoreRestGet("app-data/sites", idToken);
        if (cancelled) return;
        if (!data || !data.fields) {
          if (lastSyncedSites.current === null) lastSyncedSites.current = "[]";
          setLoaded(true);
          return;
        }
        const rawValue = (data.fields.value && data.fields.value.stringValue) || "[]";
        if (rawValue === lastSyncedSites.current) { setLoaded(true); return; }
        const parsed = JSON.parse(rawValue);
        // Filet de sécurité supplémentaire : si l'état local diffère déjà de la dernière version
        // connue comme synchronisée, c'est qu'une saisie est en attente d'enregistrement (le délai
        // de 500ms avant écriture n'a pas encore expiré) — ne surtout pas l'écraser avec une version
        // serveur plus ancienne, sous peine de faire disparaître ou "sauter" ce qui vient d'être tapé.
        const localActuel = JSON.stringify(sitesRefForPoll.current);
        // Ne s'applique qu'après un premier chargement réussi (lastSyncedSites déjà défini) — sinon
        // ce filet de sécurité bloquait le tout premier chargement (l'état local vide "[]" au
        // démarrage ne correspondant jamais au repère initial null), empêchant les sites d'apparaître.
        if (lastSyncedSites.current !== null && localActuel !== lastSyncedSites.current) { setLoaded(true); return; }
        const REGIMES_PAR_ANCIEN_TYPE = {
          "Onduleur 3/3": { normal: "Triphasé", secours: "Triphasé", utilisation: "Triphasé", onduleur: "Triphasé" },
          "Onduleur 3/1": { normal: "Triphasé", secours: "Monophasé", utilisation: "Monophasé", onduleur: "Monophasé" },
          "Onduleur 1/1": { normal: "Monophasé", secours: "Monophasé", utilisation: "Monophasé", onduleur: "Monophasé" },
        };
        parsed.forEach((s) => (s.equipements || []).forEach((e) => {
          if (REGIMES_PAR_ANCIEN_TYPE[e.type]) {
            e.controles = e.controles || {};
            e.controles.regimes_reseaux = REGIMES_PAR_ANCIEN_TYPE[e.type];
            e.type = "Onduleur";
          }
        }));
        parsed.forEach((s) => { s.equipements = (s.equipements || []).map(repairEquipementControles); });
        lastSyncedSites.current = rawValue;
        setSites(parsed);
        setLoaded(true);
      } catch (e) {
        console.error("[Firestore REST] Erreur lecture (sites) :", e);
        setLoaded(true);
      }
    }
    poll();
    intervalId = setInterval(poll, REST_POLL_INTERVAL_MS);
    return () => { cancelled = true; clearInterval(intervalId); };
  }, [currentUser]);

  // Migration automatique des anciennes photos stockées en base64 (avant le passage à Firebase
  // Storage) : les remplace progressivement par des URL courtes, par petits lots pour ne pas tout
  // bloquer d'un coup. Tourne en tâche de fond tant qu'il en reste.
  useEffect(() => {
    if (!loaded || !currentUser) return;
    let cancelled = false;
    let migrating = false;
    async function migrateOnce() {
      if (migrating) return;
      migrating = true;
      try {
        const idToken = await currentUser.getIdToken();
        const next = JSON.parse(JSON.stringify(sitesRefForPoll.current));
        const pending = [];
        (function walk(node) {
          if (Array.isArray(node)) { node.forEach(walk); return; }
          if (node && typeof node === "object") {
            if (typeof node.dataUrl === "string" && node.dataUrl.startsWith("data:image")) pending.push(node);
            Object.values(node).forEach(walk);
          }
        })(next);
        if (pending.length === 0 || cancelled) return;
        for (const node of pending.slice(0, 5)) {
          try {
            const blob = dataUrlToBlob(node.dataUrl);
            node.dataUrl = await firebaseStorageUpload(`photos/${uid()}.jpg`, blob, idToken);
          } catch (e) {
            console.error("[Migration photo] échec pour une photo :", e);
          }
        }
        if (!cancelled) setSites(next);
      } catch (e) {
        console.error("[Migration photo] erreur générale :", e);
      } finally {
        migrating = false;
      }
    }
    migrateOnce();
    const id = setInterval(migrateOnce, 6000);
    return () => { cancelled = true; clearInterval(id); };
  }, [loaded, currentUser]);

  // Nouvelle tentative automatique tant qu'une écriture a échoué — sans ça, un échec silencieux
  // (ex. document trop volumineux au moment T, mais qui passerait après suppression d'une photo)
  // resterait bloqué indéfiniment sans que l'utilisateur n'ait à ressaisir quoi que ce soit.
  useEffect(() => {
    if (!loaded || !currentUser) return;
    const retryId = setInterval(async () => {
      if (!saveErrorRef.current || !pendingRetrySites.current || writeInFlight.current) return;
      writeInFlight.current = true;
      const toRetry = pendingRetrySites.current;
      try {
        const idToken = await currentUser.getIdToken();
        await firestoreRestSet("app-data/sites", toRetry, Date.now(), currentUser?.email, idToken);
        lastSyncedSites.current = toRetry;
        setSaveError(false);
        saveErrorRef.current = false;
        pendingRetrySites.current = null;
      } catch (e) {
        // toujours en échec — on retentera au prochain cycle
      } finally {
        writeInFlight.current = false;
      }
    }, 10000);
    return () => clearInterval(retryId);
  }, [loaded, currentUser]);

  useEffect(() => {
    if (!loaded || !currentUser) return;
    const serialized = JSON.stringify(sites);
    if (serialized === lastSyncedSites.current) return;
    if (writeInFlight.current) return;
    lastSyncedSites.current = serialized;
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      writeInFlight.current = true;
      try {
        const idToken = await currentUser.getIdToken();
        await firestoreRestSet("app-data/sites", serialized, Date.now(), currentUser?.email, idToken);
        setSaveError(false);
        saveErrorRef.current = false;
        pendingRetrySites.current = null;
      } catch (e) {
        console.error("[Firestore REST] Échec d'écriture (sites) :", e);
        const tropVolumineux = /400|too large|exceeds|maximum size/i.test(String(e && e.message));
        lastSyncedSites.current = null;
        saveErrorRef.current = true;
        pendingRetrySites.current = serialized;
        setSaveError(tropVolumineux ? "taille" : true);
      } finally {
        writeInFlight.current = false;
      }
    }, 500);
    return () => clearTimeout(saveTimer.current);
  }, [sites, loaded, currentUser]);

  useEffect(() => {
    let cancelled = false;
    let intervalId = null;
    async function poll() {
      if (!currentUser) return;
      if (ivWriteInFlight.current) return;
      try {
        const idToken = await currentUser.getIdToken();
        const data = await firestoreRestGet("app-data/interventions", idToken);
        if (cancelled) return;
        if (!data || !data.fields) { if (lastSyncedIv.current === null) lastSyncedIv.current = "[]"; setIvLoaded(true); return; }
        const rawValue = (data.fields.value && data.fields.value.stringValue) || "[]";
        if (rawValue === lastSyncedIv.current) { setIvLoaded(true); return; }
        // Même protection que pour les sites : ne pas écraser une saisie en attente d'enregistrement.
        if (lastSyncedIv.current !== null && JSON.stringify(ivRefForPoll.current) !== lastSyncedIv.current) { setIvLoaded(true); return; }
        lastSyncedIv.current = rawValue;
        setInterventions(JSON.parse(rawValue));
        setIvLoaded(true);
      } catch (e) {
        setIvLoaded(true);
      }
    }
    poll();
    intervalId = setInterval(poll, REST_POLL_INTERVAL_MS);
    return () => { cancelled = true; clearInterval(intervalId); };
  }, [currentUser]);

  useEffect(() => {
    if (!ivLoaded || !currentUser) return;
    const serialized = JSON.stringify(interventions);
    if (serialized === lastSyncedIv.current) return;
    if (ivWriteInFlight.current) return;
    lastSyncedIv.current = serialized;
    if (ivSaveTimer.current) clearTimeout(ivSaveTimer.current);
    ivSaveTimer.current = setTimeout(async () => {
      ivWriteInFlight.current = true;
      try {
        const idToken = await currentUser.getIdToken();
        await firestoreRestSet("app-data/interventions", serialized, Date.now(), currentUser?.email, idToken);
      } catch (e) {
        lastSyncedIv.current = null;
      } finally {
        ivWriteInFlight.current = false;
      }
    }, 500);
    return () => clearTimeout(ivSaveTimer.current);
  }, [interventions, ivLoaded, currentUser]);

  useEffect(() => {
    let cancelled = false;
    let intervalId = null;
    async function poll() {
      if (!currentUser) return;
      if (clientsWriteInFlight.current) return;
      try {
        const idToken = await currentUser.getIdToken();
        const data = await firestoreRestGet("app-data/clients", idToken);
        if (cancelled) return;
        if (!data || !data.fields) { if (lastSyncedClients.current === null) lastSyncedClients.current = "[]"; setClientsLoaded(true); return; }
        const rawValue = (data.fields.value && data.fields.value.stringValue) || "[]";
        if (rawValue === lastSyncedClients.current) { setClientsLoaded(true); return; }
        if (lastSyncedClients.current !== null && JSON.stringify(clientsRefForPoll.current) !== lastSyncedClients.current) { setClientsLoaded(true); return; }
        lastSyncedClients.current = rawValue;
        setClientsRegistry(JSON.parse(rawValue));
        setClientsLoaded(true);
      } catch (e) {
        setClientsLoaded(true);
      }
    }
    poll();
    intervalId = setInterval(poll, REST_POLL_INTERVAL_MS);
    return () => { cancelled = true; clearInterval(intervalId); };
  }, [currentUser]);

  useEffect(() => {
    if (!clientsLoaded || !currentUser) return;
    const serialized = JSON.stringify(clientsRegistry);
    if (serialized === lastSyncedClients.current) return;
    if (clientsWriteInFlight.current) return;
    lastSyncedClients.current = serialized;
    if (clientsSaveTimer.current) clearTimeout(clientsSaveTimer.current);
    clientsSaveTimer.current = setTimeout(async () => {
      clientsWriteInFlight.current = true;
      try {
        const idToken = await currentUser.getIdToken();
        await firestoreRestSet("app-data/clients", serialized, Date.now(), currentUser?.email, idToken);
      } catch (e) {
        lastSyncedClients.current = null;
      } finally {
        clientsWriteInFlight.current = false;
      }
    }, 500);
    return () => clearTimeout(clientsSaveTimer.current);
  }, [clientsRegistry, clientsLoaded, currentUser]);

  useEffect(() => {
    let cancelled = false;
    let intervalId = null;
    async function poll() {
      if (!currentUser) return;
      if (caracWriteInFlight.current) return;
      try {
        const idToken = await currentUser.getIdToken();
        const data = await firestoreRestGet("app-data/caracteristiques", idToken);
        if (cancelled) return;
        if (!data || !data.fields) { if (lastSyncedCarac.current === null) lastSyncedCarac.current = "{}"; setCaracLoaded(true); return; }
        const rawValue = (data.fields.value && data.fields.value.stringValue) || "{}";
        if (rawValue === lastSyncedCarac.current) { setCaracLoaded(true); return; }
        if (lastSyncedCarac.current !== null && JSON.stringify(caracRefForPoll.current) !== lastSyncedCarac.current) { setCaracLoaded(true); return; }
        lastSyncedCarac.current = rawValue;
        setCaracteristiquesLibrary(JSON.parse(rawValue));
        setCaracLoaded(true);
      } catch (e) {
        setCaracLoaded(true);
      }
    }
    poll();
    intervalId = setInterval(poll, REST_POLL_INTERVAL_MS);
    return () => { cancelled = true; clearInterval(intervalId); };
  }, [currentUser]);

  useEffect(() => {
    if (!caracLoaded || !currentUser) return;
    const serialized = JSON.stringify(caracteristiquesLibrary);
    if (serialized === lastSyncedCarac.current) return;
    if (caracWriteInFlight.current) return;
    lastSyncedCarac.current = serialized;
    if (caracSaveTimer.current) clearTimeout(caracSaveTimer.current);
    caracSaveTimer.current = setTimeout(async () => {
      caracWriteInFlight.current = true;
      try {
        const idToken = await currentUser.getIdToken();
        await firestoreRestSet("app-data/caracteristiques", serialized, Date.now(), currentUser?.email, idToken);
      } catch (e) {
        lastSyncedCarac.current = null;
      } finally {
        caracWriteInFlight.current = false;
      }
    }, 500);
    return () => clearTimeout(caracSaveTimer.current);
  }, [caracteristiquesLibrary, caracLoaded, currentUser]);

  // Ajoute une valeur à la bibliothèque pour un type d'équipement + champ donné, si elle n'y est
  // pas déjà (et n'est pas vide) — appelée quand l'utilisateur tape une nouvelle valeur.
  const apprendreCaracteristique = (eqType, fieldKey, valeur) => {
    if (!valeur || !valeur.trim()) return;
    setCaracteristiquesLibrary((prev) => {
      const pourType = prev[eqType] || {};
      const existantes = pourType[fieldKey] || [];
      if (existantes.some((v) => v.trim().toLowerCase() === valeur.trim().toLowerCase())) return prev;
      return { ...prev, [eqType]: { ...pourType, [fieldKey]: [...existantes, valeur.trim()] } };
    });
  };

  // Génère le rapport (Rapport ou Rapport d'intervention) et le télécharge en .docx
  // réel (compatible Microsoft Word ET Pages sur Mac), entièrement modifiable.
  useEffect(() => {
    if (!printSite && !printIv && !printAnnexeSite) return;
    let cancelled = false;
    (async () => {
      try {
        if (printSite) {
          const blob = await generateSiteDocx(printSite, sites);
          if (!cancelled) downloadBlob(blob, `Rapport_${(printSite.nom || printSite.local || "site").replace(/[^a-z0-9]+/gi, "_")}.docx`);
        } else if (printIv) {
          const blob = await generateInterventionDocx(printIv);
          if (!cancelled) downloadBlob(blob, `RI_${(printIv.numeroRI || "intervention").replace(/[^a-z0-9]+/gi, "_")}.docx`);
        } else if (printAnnexeSite) {
          const blob = await generateAnnexePhotosDocx(printAnnexeSite);
          if (!cancelled) downloadBlob(blob, `Annexe_photos_${(printAnnexeSite.nom || printAnnexeSite.local || "site").replace(/[^a-z0-9]+/gi, "_")}.docx`);
        }
      } catch (e) {
        // best effort — génération impossible (ex. données incomplètes)
      }
      if (!cancelled) { setPrintSite(null); setPrintIv(null); setPrintAnnexeSite(null); }
    })();
    return () => { cancelled = true; };
  }, [printSite, printIv, printAnnexeSite]);

  function requestPrintSite(site) {
    const warnings = siteExportWarnings(site);
    if (warnings.length) setExportConfirm({ kind: "site", data: site, warnings });
    else setPrintSite(site);
  }
  function requestPrintIv(iv) {
    const warnings = ivExportWarnings(iv);
    if (warnings.length) setExportConfirm({ kind: "iv", data: iv, warnings });
    else setPrintIv(iv);
  }

  function updateSite(id, updater) { setSites((prev) => prev.map((s) => (s.id === id ? updater(s) : s))); }
  function addSite() {
    const s = emptySite();
    setSites((prev) => [s, ...prev]);
    setSelectedId(s.id);
  }
  // Reprend un site déjà existant (visite précédente) : conserve nom, client, locaux, et reprend
  // chaque équipement (caractéristiques gardées, mesures remises à vierge) — pratique pour repartir
  // sur une nouvelle visite annuelle sans tout ressaisir.
  function reprendreSite(source) {
    const fresh = emptySite();
    fresh.nom = source.nom;
    fresh.client = source.client;
    fresh.local = source.local;
    fresh.emailEnvoi = source.emailEnvoi || "";
    fresh.locaux = (source.locaux || []).map((l) => ({ ...l, id: uid() }));
    const localIdMap = {};
    (source.locaux || []).forEach((l, i) => { localIdMap[l.id] = fresh.locaux[i] ? fresh.locaux[i].id : ""; });
    fresh.equipements = (source.equipements || []).map((eq) => {
      const copy = dupliquerEquipementPourNouvelleVisite(eq);
      copy.localId = localIdMap[eq.localId] || (fresh.locaux[0] ? fresh.locaux[0].id : "");
      return copy;
    });
    setSites((prev) => [fresh, ...prev]);
    setSelectedId(fresh.id);
    setReprendreSiteOpen(false);
  }
  function addSiteForDate(dateISO) {
    const s = emptySite();
    s.rapport.date = dateISO;
    setSites((prev) => [s, ...prev]);
    setSelectedId(s.id);
  }
  function deleteSite(id) {
    setSites((prev) => prev.filter((s) => s.id !== id));
    setSelectedId(null);
  }

  function updateIntervention(id, updater) { setInterventions((prev) => prev.map((iv) => (iv.id === id ? updater(iv) : iv))); }
  function createIntervention(site, eq) {
    const numeroRI = nextNumeroRI(interventions);
    const iv = site ? prefillInterventionFromSite(site, eq, numeroRI) : emptyIntervention(numeroRI);
    setInterventions((prev) => [iv, ...prev]);
    setSelectedId(null);
    setSelectedIvId(iv.id);
  }
  function addInterventionForDate(dateISO) {
    const iv = emptyIntervention(nextNumeroRI(interventions));
    iv.date = dateISO;
    setInterventions((prev) => [iv, ...prev]);
    setSelectedIvId(iv.id);
  }
  function deleteIntervention(id) {
    setInterventions((prev) => prev.filter((iv) => iv.id !== id));
    setSelectedIvId(null);
  }

  // Sauvegarde manuelle : exporte toutes les données (sites + rapports d'intervention) dans un
  // fichier téléchargeable, et permet de les recharger ensuite (autre appareil, restauration…).
  const importInputRef = useRef(null);
  const [importError, setImportError] = useState(false);

  function exportData() {
    const payload = { app: "HT Maintenance", version: 1, exportedAt: new Date().toISOString(), sites, interventions };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const filename = `HT-Maintenance_sauvegarde_${todayISO()}.json`;
    downloadBlob(blob, filename);
  }

  function importData(file) {
    setImportError(false);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target.result);
        if (!Array.isArray(data.sites) || !Array.isArray(data.interventions)) throw new Error("format invalide");
        data.sites.forEach((s) => { s.equipements = (s.equipements || []).map(repairEquipementControles); });
        setSites(data.sites);
        setInterventions(data.interventions);
      } catch (err) {
        setImportError(true);
      }
    };
    reader.onerror = () => setImportError(true);
    reader.readAsText(file);
  }

  const selected = sites.find((s) => s.id === selectedId) || null;
  const selectedIv = interventions.find((iv) => iv.id === selectedIvId) || null;

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@500;600;700&display=swap');
        .print-only { display: none; }
        @media print {
          .no-print { display: none !important; }
          .print-only { display: block !important; }
        }
        .app-shell { padding: 24px; }
        .site-row, .iv-row { display: flex; align-items: center; gap: 14px; }
        .site-row-meta, .iv-row-meta { flex: 0 0 130px; }
        @media (max-width: 720px) {
          .app-shell { padding: 12px; }
          .site-row, .iv-row { flex-wrap: wrap; align-items: flex-start; gap: 6px 14px; padding: 12px !important; }
          .site-row-main, .iv-row-main { flex-basis: 100% !important; order: -1; }
          .site-row-meta, .iv-row-meta { flex: 1 1 auto !important; width: auto !important; }
          .tab-bar-scroll { overflow-x: auto; flex-wrap: nowrap !important; -webkit-overflow-scrolling: touch; padding-bottom: 4px; }
          .tab-bar-scroll::-webkit-scrollbar { height: 4px; }
          .hide-mobile { display: none !important; }
        }
      `}</style>

      <div className="no-print app-shell" style={{ position: "relative", minHeight: "100%", background: "#F1F3F6", fontFamily: "'Inter', system-ui, -apple-system, sans-serif", color: "#1A1F26" }}>
        <div style={{ maxWidth: 1100, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 18, flexWrap: "wrap", gap: 12 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <img src={LOGO_DARK} alt="HT Maintenance" style={{ width: 44, height: 44, borderRadius: 10, objectFit: "cover", boxShadow: "0 6px 18px rgba(10,93,168,0.35)" }} />
              <div>
                <h1 style={{ margin: 0, fontSize: 20, fontWeight: 800, letterSpacing: 0.3, fontFamily: "'Rajdhani', 'Inter', sans-serif", textTransform: "uppercase" }}>
                  HT <span style={{ color: BRAND.amber }}>Maintenance</span>
                </h1>
                <div style={{ fontSize: 12, color: "#5B6B7D" }}>
                  {selected ? "Fiche site" : selectedIv ? "Rapport d'intervention" : view === "sites" ? "Suivi des interventions de maintenance préventive HT" : view === "interventions" ? "Rapports d'intervention" : "Calendrier des interventions"}
                </div>
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
              {currentUser && (
                <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, color: "#8B96A3", marginRight: 4 }}>
                  <span className="hide-mobile">{currentUser.email}</span>
                  <button onClick={onLogout} style={{ ...btnGhost(), padding: "6px 10px" }} title="Se déconnecter">
                    Déconnexion
                  </button>
                </div>
              )}
              {!selected && !selectedIv && (
                <>
                  <button onClick={exportData} style={btnGhost()} title="Télécharger une sauvegarde de toutes les données">
                    <Download size={14} /> <span className="hide-mobile">Sauvegarder</span>
                  </button>
                  <button onClick={() => importInputRef.current && importInputRef.current.click()} style={btnGhost()} title="Recharger une sauvegarde précédente">
                    <Upload size={14} /> <span className="hide-mobile">Restaurer</span>
                  </button>
                  <input
                    ref={importInputRef}
                    type="file"
                    accept="application/json"
                    style={{ display: "none" }}
                    onChange={(e) => { if (e.target.files && e.target.files[0]) importData(e.target.files[0]); e.target.value = ""; }}
                  />
                </>
              )}
              {!selected && !selectedIv && view === "sites" && (
                <div style={{ position: "relative", display: "flex", gap: 8 }}>
                  <button onClick={() => setGererClientsOpen(true)} style={btnGhost(BRAND.blue)} title="Enregistrer un client (nom + e-mail) à l'avance, sans créer de site">
                    <Building2 size={14} /> <span className="hide-mobile">Gérer les clients</span>
                  </button>
                  <button onClick={() => setReprendreSiteOpen((o) => !o)} disabled={sites.length === 0}
                    style={{ ...btnGhost(BRAND.blue), opacity: sites.length === 0 ? 0.4 : 1, cursor: sites.length === 0 ? "not-allowed" : "pointer" }}
                    title="Reprendre un site déjà créé (nom, locaux et équipements) pour une nouvelle visite">
                    <RefreshCw size={14} /> <span className="hide-mobile">Reprendre un site existant</span>
                  </button>
                  {reprendreSiteOpen && sites.length > 0 && (
                    <div style={{ position: "absolute", right: 0, top: "110%", background: "#F7F8FA", border: "1px solid #D8DEE5", borderRadius: 10, overflow: "hidden", zIndex: 50, minWidth: 260, maxHeight: 320, overflowY: "auto", boxShadow: "0 12px 30px rgba(0,0,0,0.4)" }}>
                      {sites.map((s) => (
                        <div key={s.id} onClick={() => reprendreSite(s)} style={{ padding: "9px 14px", fontSize: 12, color: "#3E4A5C", cursor: "pointer", borderBottom: "1px solid #E2E6EB" }}
                          onMouseEnter={(e) => (e.currentTarget.style.background = "#E2E6EB")} onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}>
                          <div style={{ fontWeight: 700 }}>{s.nom || s.local || "Site sans nom"}</div>
                          <div style={{ fontSize: 10.5, color: "#8B96A3" }}>{s.client || "Client non renseigné"} · {s.rapport?.date || "date inconnue"}</div>
                        </div>
                      ))}
                    </div>
                  )}
                  <button onClick={addSite} style={btnPrimary()}><Plus size={16} /> Nouvelle intervention</button>
                </div>
              )}
            </div>
          </div>
          {importError && (
            <div style={{ background: "rgba(239,68,68,0.08)", border: "1px solid rgba(239,68,68,0.3)", color: "#B91C1C", borderRadius: 10, padding: "10px 14px", fontSize: 12.5, marginBottom: 14 }}>
              Le fichier sélectionné n'est pas une sauvegarde valide. Vérifiez que vous avez bien choisi un fichier exporté depuis cette application.
            </div>
          )}

          {!selected && !selectedIv && (
            <div style={{ display: "flex", gap: 6, marginBottom: 20, flexWrap: "wrap" }}>
              <button onClick={() => setView("sites")} style={{
                display: "flex", alignItems: "center", gap: 6, padding: "8px 16px", borderRadius: 999,
                border: view === "sites" ? "1px solid #FFC10755" : "1px solid #D8DEE5", background: view === "sites" ? "rgba(255,193,7,0.12)" : "transparent",
                color: view === "sites" ? BRAND.amber : "#5B6B7D", fontSize: 12.5, fontWeight: 600, cursor: "pointer",
              }}>
                <Building2 size={13} /> Sites
              </button>
              <button onClick={() => setView("interventions")} style={{
                display: "flex", alignItems: "center", gap: 6, padding: "8px 16px", borderRadius: 999,
                border: view === "interventions" ? "1px solid #FFC10755" : "1px solid #D8DEE5", background: view === "interventions" ? "rgba(255,193,7,0.12)" : "transparent",
                color: view === "interventions" ? BRAND.amber : "#5B6B7D", fontSize: 12.5, fontWeight: 600, cursor: "pointer",
              }}>
                <ClipboardList size={13} /> Rapports d'intervention
              </button>
              <button onClick={() => setView("calendrier")} style={{
                display: "flex", alignItems: "center", gap: 6, padding: "8px 16px", borderRadius: 999,
                border: view === "calendrier" ? "1px solid #FFC10755" : "1px solid #D8DEE5", background: view === "calendrier" ? "rgba(255,193,7,0.12)" : "transparent",
                color: view === "calendrier" ? BRAND.amber : "#5B6B7D", fontSize: 12.5, fontWeight: 600, cursor: "pointer",
              }}>
                <Clock size={13} /> Calendrier
              </button>
            </div>
          )}

          {saveError && (
            <div style={{ background: "rgba(239,68,68,0.1)", border: "1px solid rgba(239,68,68,0.3)", color: "#B91C1C", borderRadius: 10, padding: "10px 14px", fontSize: 12.5, marginBottom: 14, fontWeight: saveError === "taille" ? 700 : 400 }}>
              {saveError === "taille"
                ? "⚠ Sauvegarde impossible : trop de photos accumulées sur vos sites (limite de taille dépassée). Supprimez quelques anciennes photos pour débloquer l'enregistrement — nouvelle tentative automatique en cours."
                : "La sauvegarde a échoué — vos dernières modifications ne sont peut-être pas enregistrées. Nouvelle tentative automatique en cours."}
            </div>
          )}

          {selected ? (
            <SiteDetail site={selected} allSites={sites} update={(updater) => updateSite(selected.id, updater)} onBack={() => setSelectedId(null)} onDelete={deleteSite} onPrint={requestPrintSite} onPrintAnnexe={setPrintAnnexeSite} onCreateIntervention={createIntervention} clientsRegistry={clientsRegistry} caracteristiquesLibrary={caracteristiquesLibrary} apprendreCaracteristique={apprendreCaracteristique} />
          ) : selectedIv ? (
            <InterventionEditor iv={selectedIv} update={(updater) => updateIntervention(selectedIv.id, updater)} onBack={() => setSelectedIvId(null)} onDelete={deleteIntervention} onPrint={requestPrintIv} />
          ) : view === "sites" ? (
            !loaded ? <div style={{ textAlign: "center", padding: 60, color: "#8B96A3", fontSize: 13 }}>Chargement…</div> : <Overview sites={sites} onOpen={setSelectedId} onNew={addSite} />
          ) : view === "interventions" ? (
            !ivLoaded ? <div style={{ textAlign: "center", padding: 60, color: "#8B96A3", fontSize: 13 }}>Chargement…</div> : <InterventionsOverview interventions={interventions} sites={sites} onOpen={setSelectedIvId} onCreate={createIntervention} />
          ) : (
            !loaded || !ivLoaded ? <div style={{ textAlign: "center", padding: 60, color: "#8B96A3", fontSize: 13 }}>Chargement…</div> : (
              <CalendarView sites={sites} interventions={interventions} onOpenSite={setSelectedId} onOpenIntervention={setSelectedIvId} onCreateForDate={addSiteForDate} onCreateInterventionForDate={addInterventionForDate} />
            )
          )}
        </div>
      </div>

      {gererClientsOpen && (
        <GererClientsModal registry={clientsRegistry} setRegistry={setClientsRegistry} allSites={sites} onClose={() => setGererClientsOpen(false)} />
      )}

      {exportConfirm && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(4,9,16,0.72)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 200, padding: 16 }} onClick={() => setExportConfirm(null)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#FFFFFF", border: "1px solid #D8DEE5", borderRadius: 14, padding: 22, maxWidth: 420, width: "100%", boxShadow: "0 20px 50px rgba(0,0,0,0.3)" }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: "#1A1F26", marginBottom: 4 }}>Quelques champs semblent incomplets</div>
            <div style={{ fontSize: 12, color: "#8B96A3", marginBottom: 14 }}>Le rapport Word peut quand même être généré — voici ce qui manque :</div>
            <ul style={{ margin: 0, paddingLeft: 20, marginBottom: 18 }}>
              {exportConfirm.warnings.map((w, i) => (
                <li key={i} style={{ fontSize: 12.5, color: "#3E4A5C", marginBottom: 4 }}>{w}</li>
              ))}
            </ul>
            <div style={{ display: "flex", justifyContent: "flex-end", gap: 10 }}>
              <button onClick={() => setExportConfirm(null)} style={btnGhost()}>Annuler, je complète</button>
              <button
                onClick={() => {
                  if (exportConfirm.kind === "site") setPrintSite(exportConfirm.data);
                  else setPrintIv(exportConfirm.data);
                  setExportConfirm(null);
                }}
                style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#FFC107", border: "none", color: "#1A1F26", borderRadius: 8, padding: "9px 16px", fontSize: 12.5, fontWeight: 700, cursor: "pointer" }}
              >
                Générer quand même
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

